sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float kelvin;
uniform float strength;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float3 light(float kelvin) {
    float t = clamp(kelvin, 1000.0, 40000.0) / 100.0;
    float r = t <= 66.0 ? 255.0 : 329.698727446 * pow(t - 60.0, -0.1332047592);
    float g = t <= 66.0 ? 99.4708025861 * log(t) - 161.1195681661 : 288.1221695283 * pow(t - 60.0, -0.0755148492);
    float b = t >= 66.0 ? 255.0 : (t <= 19.0 ? 0.0 : 138.5177312231 * log(t - 10.0) - 305.0447927307);
    return clamp(float3(r, g, b) / 255.0, 0.0, 1.0);
}
half4 main(float2 coord) {
    half4 c = image.eval(coord);
    if (c.a <= 0.0) return c;
    float3 base = float3(c.rgb) / float(c.a);
    float3 rgb = base * light(kelvin) / light(6500.0);
    rgb *= luma(base) / max(luma(rgb), 0.0001);
    rgb = mix(base, rgb, clamp(strength, 0.0, 1.0));
    return half4(half3(clamp(rgb, 0.0, 1.0)) * c.a, c.a);
}
